// ---------------------------------------------------------------- placeable dishes (tools/kitchen/props.py)
// Feasts hold 4 servings eaten straight from the block; plates hold 1-4 items, one in, one out; drinks are props
// you drink from. Nothing here ever creates food from nothing.
var $KitchenIntProp = Java.loadClass('net.minecraft.world.level.block.state.properties.IntegerProperty')
var $KitchenStateProps = Java.loadClass('net.minecraft.world.level.block.state.properties.BlockStateProperties')
var KITCHEN_SERVINGS = $KitchenIntProp.create('servings', 1, 4)
var KITCHEN_FACING = $KitchenStateProps.HORIZONTAL_FACING

var KitchenDish = {
  setServings: (b, n) => {
    b.set(b.blockState.block, { facing: String(b.properties.get('facing')), servings: String(n) })
  },
  sound: (b, id) => {
    try { b.level.playSound(null, b.pos, id, 'players', 0.8, 1.0) } catch (err) { }
  },
  feed: (eater, d, nutrition, saturation) => {
    eater.addFood(nutrition, saturation)
    for (var fi = 0; fi < d.effects.length; fi++) {
      var fx = d.effects[fi]
      try { eater.potionEffects.add(fx[0], fx[1], fx[2]) } catch (err) { console.error('christmas-kitchen effect ' + fx[0] + ': ' + err) }
    }
  },
  pickUp: (e, d) => {
    var who = e.player
    if (!who.isShiftKeyDown() || !e.item.isEmpty()) return false
    if (d.kind == 'feast' && Number(e.block.properties.get('servings')) != 4) return false
    var count = d.kind == 'plate' ? Number(e.block.properties.get('servings')) : 1
    e.block.set('minecraft:air')
    who.give(Item.of(d.id, count))
    KitchenDish.sound(e.block, 'minecraft:block.wool.break')
    return true
  },
  use: (e, d) => {
    try {
      var p = e.player, b = e.block
      if (!p || !b) return
      if (KitchenDish.pickUp(e, d)) return
      if (d.kind == 'plate') {
        var n = Number(b.properties.get('servings'))
        if (e.item.id == d.id && n < 4) {
          if (!p.isCreative()) e.item.shrink(1)
          KitchenDish.setServings(b, n + 1)
          KitchenDish.sound(b, 'minecraft:block.wool.place')
        } else {
          if (n > 1) KitchenDish.setServings(b, n - 1)
          else b.set('minecraft:air')
          p.give(Item.of(d.id))
          KitchenDish.sound(b, 'minecraft:entity.item.pickup')
        }
        return
      }
      if (d.kind == 'prop') return
      if (d.kind == 'drink') {
        KitchenDish.feed(p, d, d.nutrition, d.saturation)
        b.set('minecraft:air')
        if (!p.isCreative() && d.container) p.give(Item.of(d.container))
        KitchenDish.sound(b, 'minecraft:entity.generic.drink')
        return
      }
      // feast: a serving straight from the dish
      if (!p.isCreative() && !p.foodData.needsFood()) {
        try { p.statusMessage = Text.translatable('christmascraft.kitchen.too_full') } catch (err) { }
        return
      }
      var left = Number(b.properties.get('servings'))
      KitchenDish.feed(p, d, Math.ceil(d.nutrition / 4), d.saturation)
      if (left > 1) KitchenDish.setServings(b, left - 1)
      else b.set('minecraft:air')
      KitchenDish.sound(b, 'minecraft:entity.generic.eat')
    } catch (err) {
      console.error('christmas-kitchen dish ' + d.id + ': ' + err)
    }
  },
}

